--- URLs is a library for working with URLs.
--- @class urls
local urls = {}


--- Values maps a string key to a list of values. It is typically used for query parameters and form values. Unlike in the `http.header` map, the keys in a `values` map are case-sensitive.
--- @class urls_values
local urls_values = {}


--- Adds the key and value to the values. It appends to any existing values associated with key.
--- @param key string The key to add. It must not be empty.
--- @param value string The value to add. It must not be empty.
function urls_values:add(key, value)
end

--- Sets the key to value. It replaces any existing values associated with key.
--- @param key string The key to add. It must not be empty.
--- @param value string The value to add. It must not be empty.
function urls_values:set(key, value)
end

--- Gets the first value associated with the given key. If there are no values associated with the key, Get returns "".
--- @param key string The key to get.
--- @return string value The first value associated with the given key.
function urls_values:get(key)
end

--- Returns true if the values contains the specified key, false otherwise.
--- @param key string The key to check.
--- @return boolean has True if the values contains the specified key, false otherwise.
function urls_values:has(key)
end

--- Deletes the values associated with key.
--- @param key string The key to delete.
function urls_values:del(key)
end

--- Encodes the values into "URL encoded" form sorted by key.
--- @return string encoded The URL encoded form of the values.
function urls_values:string()
end

--- Creates a values from the URL encoded form. It is the inverse operation of string.
--- @param encoded string The URL encoded form of the values.
--- @return urls_values values The values created from the URL encoded form.
function urls_values:parse(encoded)
end

--- Structured URL
--- @class urls_url
local urls_url = {}


--- Return hostname without port numbers.
--- @return string hostname URLs hostname
function urls_url:hostname()
end

--- Parses a URL in the context of the receiver. The provided URL may be relative or absolute.
--- @param ref string 
--- @return urls_url url 
function urls_url:parse(ref)
end

--- Reassembles the URL into a valid URL string.
--- @return string url 
function urls_url:string()
end

--- Returns a new URL with the provided path elements joined to any existing path and the resulting path cleaned of any ./ or ../ elements. Any sequences of multiple / characters will be reduced to a single /.
--- @param ... string 
--- @return urls_url url 
